"""Small standard-library YAML subset reader and writer for jd CLI inputs."""
import json
import re


def _scalar(s):
    s=s.strip()
    if not s: return None
    if s in ('null','Null','NULL','~'): return None
    if s.lower() in ('true','false'): return s.lower()=='true'
    if s.startswith('[') or s.startswith('{'):
        # YAML flow syntax is largely JSON; quote bare keys and single strings where practical.
        try: return json.loads(s)
        except Exception:
            try: return json.loads(re.sub(r"'([^']*)'", lambda m: json.dumps(m.group(1)), s))
            except Exception: pass
    if s.startswith('"'):
        try: return json.loads(s)
        except Exception: return s[1:-1]
    if s.startswith("'") and s.endswith("'"): return s[1:-1].replace("''", "'")
    if re.fullmatch(r'[-+]?(?:0|[1-9][0-9]*)(?:_[0-9]+)*',s):
        try: return int(s.replace('_',''))
        except ValueError: pass
    if re.fullmatch(r'[-+]?(?:[0-9]+\.[0-9]*|\.[0-9]+|[0-9]+[eE][-+]?[0-9]+|[0-9]+\.[0-9]*[eE][-+]?[0-9]+)',s):
        try: return float(s.replace('_',''))
        except ValueError: pass
    return s


def loads(src):
    lines=[]
    for raw in src.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#') or raw.strip() in ('---','...'): continue
        # Strip comments outside quotes.
        quote=None; cut=len(raw)
        for i,c in enumerate(raw):
            if quote:
                if c==quote and (i==0 or raw[i-1]!='\\'): quote=None
            elif c in "'\"": quote=c
            elif c=='#' and (i==0 or raw[i-1].isspace()): cut=i; break
        raw=raw[:cut].rstrip()
        if raw.strip(): lines.append((len(raw)-len(raw.lstrip(' ')),raw.lstrip(' ')))
    if not lines: return None
    def parse(i, indent):
        seq=lines[i][1].startswith('- ') or lines[i][1]=='-'
        out=[] if seq else {}
        while i<len(lines) and lines[i][0]==indent:
            txt=lines[i][1]
            if seq:
                if not (txt=='-' or txt.startswith('- ')): break
                val=txt[1:].strip(); i+=1
                if not val:
                    if i<len(lines) and lines[i][0]>indent: item,i=parse(i,lines[i][0]); out.append(item)
                    else: out.append(None)
                elif re.match(r'^[^\[\]{}]+:\s*',val):
                    k,v=val.split(':',1); obj={k.strip():_scalar(v) if v.strip() else None}
                    if i<len(lines) and lines[i][0]>indent:
                        child,i=parse(i,lines[i][0])
                        if isinstance(child,dict): obj.update(child)
                    out.append(obj)
                else: out.append(_scalar(val))
            else:
                if ':' not in txt: break
                k,v=txt.split(':',1); k=str(_scalar(k)); v=v.strip(); i+=1
                if v in ('|','>','|-','>-','|+','>+'):
                    chunks=[]
                    while i<len(lines) and lines[i][0]>indent: chunks.append(lines[i][1]); i+=1
                    out[k]=('\n' if v.startswith('|') else ' ').join(chunks)+('\n' if v.endswith('+') or v in ('|','>') else '')
                elif v:
                    out[k]=_scalar(v)
                elif i<len(lines) and lines[i][0]>indent:
                    out[k],i=parse(i,lines[i][0])
                else: out[k]=None
        return out,i
    val,i=parse(0,lines[0][0])
    if i<len(lines):
        # tolerate unexpected indentation by parsing remaining documents as list items
        raise ValueError('invalid YAML indentation')
    return val


def _plain(v):
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v,(int,float)): return json.dumps(v,allow_nan=False)
    if isinstance(v,str):
        if v and re.fullmatch(r'[A-Za-z0-9_./-]+',v) and v.lower() not in ('null','true','false','~') and not re.match(r'^[-+]?\d',v): return v
        return json.dumps(v,ensure_ascii=False)
    return json.dumps(v,ensure_ascii=False,separators=(',',':'))


def dumps(value):
    def emit(v,indent):
        pad=' '*indent
        if isinstance(v,dict):
            if not v: return pad+'{}'
            rows=[]
            for k,x in v.items():
                key=_plain(str(k))
                if isinstance(x,(dict,list)) and x: rows.append(pad+key+':\n'+emit(x,indent+2))
                else: rows.append(pad+key+': '+_plain(x))
            return '\n'.join(rows)
        if isinstance(v,list):
            if not v: return pad+'[]'
            rows=[]
            for x in v:
                if isinstance(x,(dict,list)) and x: rows.append(pad+'-\n'+emit(x,indent+2))
                else: rows.append(pad+'- '+_plain(x))
            return '\n'.join(rows)
        return pad+_plain(v)
    return emit(value,0)+'\n'
